<?php require '../includes/functions.php';$u=require_login();$id=(int)($_GET['id']??0);$sql='SELECT a.* FROM grievance_attachments a JOIN grievances g ON g.id=a.grievance_id WHERE g.id=?';$params=[$id];if($u['role']==='citizen'){$sql.=' AND g.citizen_id=?';$params[]=$u['id'];}elseif($u['role']==='department_admin'){$sql.=' AND g.department_id=?';$params[]=$u['department_id'];}$q=db()->prepare($sql);$q->execute($params);$a=$q->fetch();if(!$a){http_response_code(404);exit('Attachment not found.');}$path=UPLOAD_DIR.'/'.$a['stored_name'];if(!is_file($path)){http_response_code(404);exit('File not found.');}header('Content-Type: '.$a['mime_type']);header('Content-Disposition: attachment; filename="'.str_replace('"','',basename($a['original_name'])).'"');header('Content-Length: '.filesize($path));readfile($path);
